define(['core/ajax','core/notification'],function(Ajax,Notification){'use strict';function init(config){var root=document.getElementById(config.containerid);if(!root){return;}var canvas=root.querySelector('[data-region="canvas"]');var ctx=canvas.getContext('2d');var messageEl=root.querySelector('[data-region="message"]');var scoreEl=root.querySelector('[data-region="score"]');var hintEl=root.querySelector('[data-region="targethint"]');var saveStatusEl=root.querySelector('[data-region="savestatus"]');var resetBtn=root.querySelector('[data-action="reset"]');var answerButtons=[].slice.call(root.querySelectorAll('.flwvrroom-answer'));var progressEls={waiter:root.querySelector('[data-progress="waiter"]'),menu:root.querySelector('[data-progress="menu"]'),cup:root.querySelector('[data-progress="cup"]'),table:root.querySelector('[data-progress="table"]'),cashier:root.querySelector('[data-progress="cashier"]'),quiz:root.querySelector('[data-progress="quiz"]')};var state={yaw:0,score:0,dragging:false,lastX:0,completed:{waiter:false,menu:false,cup:false,table:false,cashier:false,quiz:false},hitAreas:[],saved:false};var camera={x:0,y:1.6,z:4};var focal=720;var objects=[{id:'waiter',label:'Waiter',type:'person',pos:[-2.6,1.0,-3.2],size:[0.8,2.0,0.5],color:'#3c2f2f',points:20,message:'Waiter: Good morning. What would you like?',hint:'Good. Now click the menu, cup, table, and cashier.',speech:'Good morning. What would you like?'},{id:'menu',label:'Menu',type:'box',pos:[0.55,0.93,-2.05],size:[0.7,0.06,0.9],color:'#fff0bd',points:15,message:'Menu: coffee, tea, water, sandwich. Useful phrase: I’d like a coffee, please.',hint:'Menu learned. Click the cup or try the quiz.',speech:'Coffee. Tea. Water. Sandwich.'},{id:'cup',label:'Cup',type:'cylinder',pos:[-0.55,1.0,-2.05],size:[0.45,0.45,0.45],color:'#ffffff',points:15,message:'Cup: You drink coffee or tea from a cup.',hint:'Cup learned. Find the table and cashier.',speech:'Cup. You drink coffee from a cup.'},{id:'table',label:'Table',type:'box',pos:[0,0.65,-2.05],size:[2.3,0.35,1.25],color:'#875628',points:10,message:'Table: People sit at a table in a cafe.',hint:'Table learned. Click the cashier or answer the quiz.',speech:'Table. People sit at a table.'},{id:'cashier',label:'Cashier',type:'box',pos:[2.55,1.0,-3.7],size:[1.05,1.3,0.55],color:'#5d4037',points:15,message:'Cashier: You pay here. Useful question: How much is it?',hint:'Cashier learned. Now choose the best polite sentence in the quiz.',speech:'How much is it?'}];function resizeCanvas(){var rect=canvas.getBoundingClientRect();var dpr=Math.max(1,Math.min(2,window.devicePixelRatio||1));canvas.width=Math.floor(rect.width*dpr);canvas.height=Math.floor(rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);drawScene();}function project(point){var x=point[0],y=point[1],z=point[2];var dx=x-camera.x,dy=y-camera.y,dz=z-camera.z;var c=Math.cos(state.yaw),s=Math.sin(state.yaw);var x1=c*dx-s*dz;var z1=s*dx+c*dz;var forward=-z1;if(forward<=0.12){return null;}var rect=canvas.getBoundingClientRect();return{x:rect.width/2+(x1/forward)*focal,y:rect.height/2-(dy/forward)*focal,f:forward};}function drawPolygon(points,fill,stroke){var p=points.map(project);if(p.some(function(v){return!v;})){return;}ctx.beginPath();ctx.moveTo(p[0].x,p[0].y);for(var i=1;i<p.length;i++){ctx.lineTo(p[i].x,p[i].y);}ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle=stroke||'rgba(0,0,0,.16)';ctx.stroke();}function boxVertices(pos,size){var cx=pos[0],cy=pos[1],cz=pos[2],w=size[0],h=size[1],d=size[2];var x0=cx-w/2,x1=cx+w/2,y0=cy-h/2,y1=cy+h/2,z0=cz-d/2,z1=cz+d/2;return{A:[x0,y0,z0],B:[x1,y0,z0],C:[x1,y1,z0],D:[x0,y1,z0],E:[x0,y0,z1],F:[x1,y0,z1],G:[x1,y1,z1],H:[x0,y1,z1]};}function shade(hex,percent){var num=parseInt(hex.replace('#',''),16);var r=(num>>16)+percent;var g=((num>>8)&255)+percent;var b=(num&255)+percent;r=Math.max(0,Math.min(255,r));g=Math.max(0,Math.min(255,g));b=Math.max(0,Math.min(255,b));return'#'+(b|(g<<8)|(r<<16)).toString(16).padStart(6,'0');}function addHitArea(id,points,depth){var p=points.map(project).filter(Boolean);if(p.length<2){return;}var xs=p.map(function(v){return v.x;});var ys=p.map(function(v){return v.y;});state.hitAreas.push({id:id,depth:depth,x0:Math.min.apply(null,xs),x1:Math.max.apply(null,xs),y0:Math.min.apply(null,ys),y1:Math.max.apply(null,ys)});}function roundRect(context,x,y,width,height,radius){context.beginPath();context.moveTo(x+radius,y);context.arcTo(x+width,y,x+width,y+height,radius);context.arcTo(x+width,y+height,x,y+height,radius);context.arcTo(x,y+height,x,y,radius);context.arcTo(x,y,x+width,y,radius);context.closePath();}function drawLabel(text,pos,color){var p=project(pos);if(!p){return;}ctx.save();ctx.font='700 15px Arial';ctx.textAlign='center';var w=ctx.measureText(text).width+18;ctx.fillStyle='rgba(255,255,255,.85)';ctx.strokeStyle='rgba(0,0,0,.12)';roundRect(ctx,p.x-w/2,p.y-26,w,24,8);ctx.fill();ctx.stroke();ctx.fillStyle=color||'#241a11';ctx.fillText(text,p.x,p.y-9);ctx.restore();}function drawBox(obj){var v=boxVertices(obj.pos,obj.size);drawPolygon([v.A,v.B,v.C,v.D],shade(obj.color,-8));drawPolygon([v.E,v.F,v.G,v.H],shade(obj.color,12));drawPolygon([v.D,v.C,v.G,v.H],shade(obj.color,24));drawPolygon([v.B,v.F,v.G,v.C],shade(obj.color,-18));drawPolygon([v.A,v.E,v.H,v.D],shade(obj.color,-6));addHitArea(obj.id,Object.values(v),obj.pos[2]);drawLabel(obj.label,[obj.pos[0],obj.pos[1]+obj.size[1]/2+0.35,obj.pos[2]]);}function drawCylinder(obj){var p=project(obj.pos);if(!p){return;}var w=obj.size[0],h=obj.size[1];var radius=Math.max(8,(w/p.f)*310);var height=Math.max(12,(h/p.f)*360);ctx.save();ctx.fillStyle='rgba(0,0,0,.12)';ctx.beginPath();ctx.ellipse(p.x+8,p.y+height/2+8,radius*1.1,radius*.38,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=obj.color;ctx.strokeStyle='rgba(0,0,0,.22)';ctx.fillRect(p.x-radius,p.y-height/2,radius*2,height);ctx.strokeRect(p.x-radius,p.y-height/2,radius*2,height);ctx.beginPath();ctx.ellipse(p.x,p.y-height/2,radius,radius*.34,0,0,Math.PI*2);ctx.fillStyle='#ffffff';ctx.fill();ctx.stroke();ctx.beginPath();ctx.ellipse(p.x,p.y+height/2,radius,radius*.34,0,0,Math.PI*2);ctx.stroke();ctx.restore();addHitArea(obj.id,[[obj.pos[0]-0.35,obj.pos[1]-0.35,obj.pos[2]],[obj.pos[0]+0.35,obj.pos[1]+0.35,obj.pos[2]]],obj.pos[2]);drawLabel(obj.label,[obj.pos[0],obj.pos[1]+0.55,obj.pos[2]]);}function drawPerson(obj){drawCylinder({id:obj.id,label:obj.label,pos:obj.pos,size:[0.8,1.55,0.5],color:obj.color});var head=project([obj.pos[0],obj.pos[1]+1.12,obj.pos[2]]);if(head){var r=Math.max(16,(0.32/head.f)*330);ctx.save();ctx.fillStyle='#f1c27d';ctx.strokeStyle='rgba(0,0,0,.22)';ctx.beginPath();ctx.arc(head.x,head.y,r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();}}function drawScene(){var rect=canvas.getBoundingClientRect();ctx.clearRect(0,0,rect.width,rect.height);var grd=ctx.createLinearGradient(0,0,0,rect.height);grd.addColorStop(0,'#b9d8f4');grd.addColorStop(.48,'#f8ecd8');grd.addColorStop(1,'#d8b887');ctx.fillStyle=grd;ctx.fillRect(0,0,rect.width,rect.height);state.hitAreas=[];drawPolygon([[-6,0,-6],[6,0,-6],[6,0,5],[-6,0,5]],'#d9c7a3');drawPolygon([[-6,0,-6],[6,0,-6],[6,4,-6],[-6,4,-6]],'#f4dfbd');drawPolygon([[-6,0,5],[-6,0,-6],[-6,4,-6],[-6,4,5]],'#edc98f');drawPolygon([[6,0,-6],[6,0,5],[6,4,5],[6,4,-6]],'#e7bd82');objects.slice().sort(function(a,b){return b.pos[2]-a.pos[2];}).forEach(function(obj){if(obj.type==='box'){drawBox(obj);}else if(obj.type==='cylinder'){drawCylinder(obj);}else{drawPerson(obj);}});}function updateProgress(){Object.keys(state.completed).forEach(function(key){if(progressEls[key]){var label=key.charAt(0).toUpperCase()+key.slice(1);progressEls[key].textContent=label+': '+(state.completed[key]?'✓':'✗');}});scoreEl.textContent=state.score;}function speak(text){try{if('speechSynthesis'in window){window.speechSynthesis.cancel();var utter=new SpeechSynthesisUtterance(text);utter.lang='en-US';utter.rate=.88;window.speechSynthesis.speak(utter);}}catch(e){}}function addScore(points){state.score=Math.min(100,state.score+points);updateProgress();}function setMessage(text){messageEl.textContent=text;}function getCompletedObjects(){var completed=[];['waiter','menu','cup','table','cashier'].forEach(function(k){if(state.completed[k]){completed.push(k);}});return completed;}function saveAttempt(){if(state.saved){return;}saveStatusEl.textContent='Saving score to Moodle...';Ajax.call([{methodname:'mod_flwvrroom_submit_attempt',args:{cmid:config.cmid,score:state.score,maxscore:100,completedobjects:getCompletedObjects().join(','),completedquiz:state.completed.quiz?1:0,completed:isMissionComplete()?1:0}}])[0].then(function(response){state.saved=true;saveStatusEl.textContent='Saved to Moodle. Score: '+response.score+'/100';return response;}).catch(function(ex){saveStatusEl.textContent='Could not save yet. Check permissions, login, and AJAX service.';Notification.exception(ex);});}function isMissionComplete(){return state.completed.waiter&&state.completed.menu&&state.completed.cup&&state.completed.table&&state.completed.cashier&&state.completed.quiz;}function checkMissionComplete(){if(isMissionComplete()){setMessage('Mission complete! You can say: I’d like a coffee, please. Your score will be saved to Moodle.');hintEl.textContent='Mission complete.';saveAttempt();}}function handleObject(id){var obj=objects.filter(function(o){return o.id===id;})[0];if(!obj){return;}if(!state.completed[id]){state.completed[id]=true;addScore(obj.points);}setMessage(obj.message);hintEl.textContent=obj.hint;speak(obj.speech);drawScene();checkMissionComplete();}function clickCanvas(clientX,clientY){var rect=canvas.getBoundingClientRect();var x=clientX-rect.left,y=clientY-rect.top;var hits=state.hitAreas.filter(function(h){return x>=h.x0&&x<=h.x1&&y>=h.y0&&y<=h.y1;}).sort(function(a,b){return a.depth-b.depth;});if(hits.length){handleObject(hits[0].id);}}canvas.addEventListener('pointerdown',function(e){state.dragging=true;state.lastX=e.clientX;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',function(e){if(!state.dragging){return;}var dx=e.clientX-state.lastX;state.lastX=e.clientX;state.yaw+=dx*0.006;drawScene();});canvas.addEventListener('pointerup',function(e){state.dragging=false;clickCanvas(e.clientX,e.clientY);});canvas.addEventListener('pointercancel',function(){state.dragging=false;});window.addEventListener('keydown',function(e){if(e.key==='ArrowLeft'){state.yaw-=0.12;drawScene();}if(e.key==='ArrowRight'){state.yaw+=0.12;drawScene();}});answerButtons.forEach(function(btn){btn.addEventListener('click',function(){var correct=btn.getAttribute('data-answer')==='correct';if(correct){if(!state.completed.quiz){state.completed.quiz=true;addScore(25);}setMessage('Correct. A polite answer is: I’d like a coffee, please.');hintEl.textContent='Quiz complete. Explore any missing objects.';speak('I would like a coffee, please.');checkMissionComplete();}else{setMessage('Not correct. Try: I’d like a coffee, please.');speak('Try again. I would like a coffee, please.');}});});resetBtn.addEventListener('click',function(){state.score=0;state.completed={waiter:false,menu:false,cup:false,table:false,cashier:false,quiz:false};state.saved=false;setMessage('Welcome to FLW Café. Click the waiter, menu, cup, table, and cashier.');hintEl.textContent='Click the waiter first.';saveStatusEl.textContent='Attempt not saved yet.';updateProgress();drawScene();});window.addEventListener('resize',resizeCanvas);updateProgress();resizeCanvas();}return{init:init};});
